    public ModelAndView vendorpolicy(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String Code = request.getParameter("id");
        if (Code == null || Code == "") {
            Code = user.getLoginName();
        }

        VendorInvitation vendorInvitation1 = vendorInvitationService.readEmailId(Code);

        VendorInformation vendorInformation5 = vendorInformationService.readEmailId(Code);
        int status2 = vendorInformation5.getStatus1();
        List vendorInformation1 = vendorInformationService.readEmail(Code);

        if (vendorInformation1.isEmpty()) {
            int status = 0;
            status = vendorInformation5.getStatus1();

            if (status != 0) {
                mv.setViewName("Vendor/VendorFinalInformation");
                return mv;
            }

            String date1 = vendorInvitation1.getLinkExpireDateTime();

            LocalDateTime myDateObj = LocalDateTime.now();
            DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
            String formattedDate = myDateObj.format(myFormatObj);

            SimpleDateFormat format = new SimpleDateFormat("MM-dd-yyyy HH:mm:ss");

            Date d1 = null;
            Date d2 = null;

            d1 = format.parse(date1);
            d2 = format.parse(formattedDate);

            long diff = d2.getTime() - d1.getTime();

            if (diff < 0 || diff > 0) {

                VendorInvitation vendorInvitation = vendorInvitationService.readEmailId(Code);
                mv.getModelMap().put("vendorInvitation", vendorInvitation);

                VendorInformation vendorInformation3 = vendorInformationService.readEmailId(Code);
                int i = vendorInvitation.getId();
                List list = vendorInvitationCategoryService.readIds(i);
                mv.getModelMap().put("list", list);
                int status1 = 0;
                status1 = vendorInformation3.getStatus1();
                mv.getModelMap().put("vendorInformation3", vendorInformation3);
                VendorBuyerApproval vendorBuyerApproval = vendorBuyerApprovalService.readByVendorInvtId(vendorInformation3.getVendorInvitationId());
                mv.getModelMap().put("vendorBuyerApproval", vendorBuyerApproval);
                if (session != null) {

                    String successMessage = (String) session.getAttribute("successMessage");
                    if (successMessage != null) {
                        mv.addObject("successMessage", successMessage);
                        session.removeAttribute("successMessage");
                    }

                    String failureMessage = (String) session.getAttribute("failureMessage");
                    if (failureMessage != null) {
                        mv.addObject("failureMessage", failureMessage);
                        session.removeAttribute("failureMessage");
                    }
                }
                mv.setViewName("Vendor/VendorPolicy");

            } else {

                mv.setViewName("Vendor/VendorInfo");

            }

        } else if (status2 == 0 || status2 == 3 || status2 == 4 || status2 == 5) {
            VendorInvitation vendorInvitation = vendorInvitationService.readEmailId(Code);
            mv.getModelMap().put("vendorInvitation", vendorInvitation);
            VendorInformation vendorInformation3 = vendorInformationService.readEmailId(Code);
            int vId = vendorInformation3.getId();

            VendorSelfDeclaration declaration = vendorSelfDeclarationService.readByVendorInformationId(vId);
            mv.getModelMap().put("declaration", declaration);

            int i = vendorInformation3.getVendorInvitationId();
            List list = vendorInvitationCategoryService.readIds(i);
            mv.getModelMap().put("list", list);

            List vendorApproval1 = vendorApprovalService.readForVendorRecycled(vendorInformation3.getId());
            request.setAttribute("vendorApproval", vendorApproval1);

            VendorBuyerApproval vendorBuyerApproval = vendorBuyerApprovalService.readByVendorInvtId(vendorInformation3.getVendorInvitationId());
            mv.getModelMap().put("vendorBuyerApproval", vendorBuyerApproval);

            mv.getModelMap().put("vendorInformation3", vendorInformation3);

            if (session != null) {

                String successMessage = (String) session.getAttribute("successMessage");
                if (successMessage != null) {
                    mv.addObject("successMessage", successMessage);
                    session.removeAttribute("successMessage");
                }

                String failureMessage = (String) session.getAttribute("failureMessage");
                if (failureMessage != null) {
                    mv.addObject("failureMessage", failureMessage);
                    session.removeAttribute("failureMessage");
                }
            }

            mv.setViewName("Vendor/VendorPolicy");
        } else {
            mv.setViewName("redirect:vendorInformation.htm?act=policyUpdateLevelOneVendorInformation&id=" + Code);
        }
        return mv;
    }

