    public ModelAndView newVendor(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        HttpSession session = request.getSession();

        UserMaster user = (UserMaster) session.getAttribute("user");
        String user11 = user.getLoginName();
        VendorInformation vendorInformation = new VendorInformation();
        String vendorEmailId = request.getParameter("vendorEmailId");
        UserRights userRights = userRightsService.readByUser(user11);
        request.setAttribute("userRights", userRights);

        if (userRights.getBuyerApproval() == 1) {
            List vendorInformation1 = vendorInformationService.readInvitedVendor(user11);
            request.setAttribute("vendorInformation1", vendorInformation1);
            mv.getModelMap().put("vendorInformation1", vendorInformation1);
            mv.setViewName("Vendor/NewVendor");
        } else if (userRights.getFinancialApproval() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=finacialApproval");
        } else if (userRights.getTechnicalApproval() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=technicalApproval");
        } else if (userRights.getProcurementHead() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=procurementHeadApproval");
        } else if (userRights.getHrApproval() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=hrApproval");
        } else if (userRights.getSafetyApproval() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=safetyApproval");
        } else if (userRights.getActiveVendor() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=activeVendor");
        } else if (userRights.getAllVendor() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=allVendor");
        } else if (userRights.getItApproval() == 1) {
            mv.setViewName("redirect:vendorInformation.htm?act=itApproval");
        } else {
            mv.setViewName("redirect:vendorInformation.htm?act=allVendor");
        }

        return mv;

    }

