    public void allVendorExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }

        String searchValue = request.getParameter("searchValue") != null ? request.getParameter("searchValue") : "";

        String orderColumn = "id";
        String orderDir = "desc";

        int start = 0;
        int filteredRecords = vendorInformationService.getFilteredAllVendorCount(searchValue);

        List allVendorList = vendorInformationService.getAllVendorPagination(start, filteredRecords, searchValue, orderColumn, orderDir);

        final String ICON_PENDING = "\u23F3";
        final String ICON_APPROVED = "\u2705";
        final String ICON_RECYCLE = "\u21BA";
        final String ICON_SEND = "\u27A1";
        final String ICON_REJECT = "\u274C";
        final String ICON_NEW = "\u2728";

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("All Vendor Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        int rowNum = 0;
        int srNo = 1;

        sheet.createFreezePane(0, 1);

        Row headerRow = sheet.createRow(rowNum++);

        String[] headers = {
            "Sr.No.", "Company Name", "Email Id", "Contact No", "Status", ""
        };

        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        sheet.addMergedRegion(new CellRangeAddress(0, 0, 4, 5));

        CellStyle hyperlinkStyle = workbook.createCellStyle();
        Font hyperlinkFont = workbook.createFont();
        hyperlinkFont.setUnderline(Font.U_SINGLE);
        hyperlinkFont.setColor(IndexedColors.BLUE.getIndex());
        hyperlinkStyle.setFont(hyperlinkFont);

        if (allVendorList != null) {

            for (Iterator it = allVendorList.iterator(); it.hasNext();) {

                Object[] row = (Object[]) it.next();

                String companyName = row[1] != null ? row[1].toString() : "";
                String vendorEmailId = row[2] != null ? row[2].toString() : "";

                String countryCode = row[3] != null ? row[3].toString() : "";
                String mobileNo = row[4] != null ? row[4].toString() : "";
                String contactNo = !mobileNo.trim().isEmpty() ? "+" + countryCode + " " + mobileNo : "";

                String vendorType = row[19] != null ? row[19].toString() : "";

                StringBuilder leftStatus = new StringBuilder();
                StringBuilder rightStatus = new StringBuilder();

                if ("REGISTERED".equals(vendorType)) {

                    Integer vendorInvtId = (Integer) row[18];

                    List vendorInvitationList = vendorInvitationCategoryService.readByVendorInvtlistId(vendorInvtId);

                    Map<String, Integer> rightsMap = new HashMap<>();

                    for (Object vendorinvList : vendorInvitationList) {

                        VendorInvitationCategory v = (VendorInvitationCategory) vendorinvList;
                        String groupSubCategoryId = v.getGroupSubCategoryId();
                        GroupSubCategory groupSubCategory = groupSubCategoryService.readById(Integer.parseInt(groupSubCategoryId));

                        if (Integer.parseInt(groupSubCategory.getHr()) == 1) {
                            rightsMap.put("HR", 1);
                        }
                        if (Integer.parseInt(groupSubCategory.getHsc()) == 1) {
                            rightsMap.put("HSE", 1);
                        }
                        if (Integer.parseInt(groupSubCategory.getIt()) == 1) {
                            rightsMap.put("IT", 1);
                        }
                        if (Integer.parseInt(groupSubCategory.getTechnical()) == 1) {
                            rightsMap.put("TECHNICAL", 1);
                        }
                    }

                    Integer status = row[5] == null ? 0 : Integer.parseInt(row[5].toString());

                    // ---- Vendor ----
                    if (status == 0 || status == 3 || status == 4 || status == 5) {
                        leftStatus.append(ICON_PENDING);
                    }
                    if (status == 1 || status == 6 || status == 7 || status == 2
                            || status == 10 || status == 100 || status == 101
                            || status == 102 || status == 500 || status == 501 || status == 502 || status == 700) {
                        leftStatus.append(ICON_APPROVED);
                    }
                    leftStatus.append(" Vendor\n");

                    // ---- Buyer ----
                    if (status == 0) {
                        leftStatus.append(ICON_PENDING);
                    }
                    if (status == 2 || status == 4 || status == 5 || status == 7
                            || status == 10 || status == 100 || status == 101
                            || status == 102 || status == 500 || status == 501 || status == 700) {
                        leftStatus.append(ICON_APPROVED);
                    }
                    if (status == 3) {
                        leftStatus.append(ICON_RECYCLE);
                    }
                    if (status == 1 || status == 502) {
                        leftStatus.append(ICON_SEND);
                    }
                    if (status == 6) {
                        leftStatus.append(ICON_REJECT);
                    }
                    leftStatus.append(" Buyer\n");

                    if (status != 6) {

                        // ---- Auditor ----
                        if (row[6] != null && !"".equals(row[6].toString())) {

                            if (status == 0 || status == 1 || status == 3) {
                                leftStatus.append(ICON_PENDING);
                            }
                            if (status == 2 || status == 5 || status == 7
                                    || status == 10 || status == 101
                                    || status == 102 || status == 500
                                    || status == 501 || status == 502 || status == 700) {
                                leftStatus.append(ICON_APPROVED);
                            }
                            if (status == 4) {
                                leftStatus.append(ICON_RECYCLE);
                            }
                            if (status == 100) {
                                leftStatus.append(ICON_SEND);
                            }
                            leftStatus.append(" Auditor\n");
                        }

                        // ---- Procurement Head ----
                        if (status == 0 || status == 1 || status == 3 || status == 4 || status == 6 || status == 100) {
                            leftStatus.append(ICON_PENDING);
                        }
                        if (status == 2 || status == 10
                                || status == 102 || status == 500
                                || status == 501 || status == 502 || status == 700) {
                            leftStatus.append(ICON_APPROVED);
                        }
                        if (status == 5) {
                            leftStatus.append(ICON_RECYCLE);
                        }
                        if (status == 101) {
                            leftStatus.append(ICON_SEND);
                        }
                        if (status == 7) {
                            leftStatus.append(ICON_REJECT);
                        }
                        leftStatus.append(" Procurement Head\n");

                        if (status != 7) {

                            // ---- Compliance Officer ----
                            if (status == 0 || status == 1 || status == 2
                                    || status == 3 || status == 4 || status == 5
                                    || status == 6 || status == 7
                                    || status == 100 || status == 101
                                    || status == 102) {
                                leftStatus.append(ICON_PENDING);
                            }
                            if (status == 10 || status == 700) {
                                leftStatus.append(ICON_APPROVED);
                            }
                            if (status == 500) {
                                leftStatus.append(ICON_SEND);
                            }
                            if (status == 501) {
                                leftStatus.append(ICON_REJECT);
                            }
                            if (status == 502) {
                                leftStatus.append(ICON_RECYCLE);
                            }
                            leftStatus.append(" Compliance Officer\n");
                        }
                    }

                    // ---- Right column: dept approvals ----
                    if (status != 6 && status != 7) {

                        Integer financeFlag = row[9] == null ? 0 : Integer.parseInt(row[9].toString());
                        appendDeptStatus(rightStatus, financeFlag, "Finance", ICON_PENDING, ICON_APPROVED, ICON_RECYCLE);

                        if (rightsMap.get("TECHNICAL") != null && rightsMap.get("TECHNICAL") == 1) {
                            Integer technicalFlag = row[11] == null ? 0 : Integer.parseInt(row[11].toString());
                            appendDeptStatus(rightStatus, technicalFlag, "Technical", ICON_PENDING, ICON_APPROVED, ICON_RECYCLE);
                        }

                        if (rightsMap.get("HR") != null && rightsMap.get("HR") == 1) {
                            Integer hrFlag = row[13] == null ? 0 : Integer.parseInt(row[13].toString());
                            appendDeptStatus(rightStatus, hrFlag, "HR", ICON_PENDING, ICON_APPROVED, ICON_RECYCLE);
                        }

                        if (rightsMap.get("HSE") != null && rightsMap.get("HSE") == 1) {
                            Integer hseFlag = row[15] == null ? 0 : Integer.parseInt(row[15].toString());
                            appendDeptStatus(rightStatus, hseFlag, "HSE", ICON_PENDING, ICON_APPROVED, ICON_RECYCLE);
                        }

                        if (rightsMap.get("IT") != null && rightsMap.get("IT") == 1) {
                            Integer itFlag = row[17] == null ? 0 : Integer.parseInt(row[17].toString());
                            appendDeptStatus(rightStatus, itFlag, "IT", ICON_PENDING, ICON_APPROVED, ICON_RECYCLE);
                        }
                    }

                } else {
                    leftStatus.append(ICON_NEW).append(" New Vendor");
                }

                Row excelRow = sheet.createRow(rowNum++);
                excelRow.setHeightInPoints(60);

                excelRow.createCell(0).setCellValue(srNo++);
                excelRow.createCell(1).setCellValue(companyName);
                excelRow.createCell(2).setCellValue(vendorEmailId);
                excelRow.createCell(3).setCellValue(contactNo);

                Cell leftCell = excelRow.createCell(4);
                leftCell.setCellValue(trimTrailingNewline(leftStatus.toString()));
                leftCell.setCellStyle(wrapStyle);

                Cell rightCell = excelRow.createCell(5);
                rightCell.setCellValue(trimTrailingNewline(rightStatus.toString()));
                rightCell.setCellStyle(wrapStyle);

            }
        }

        for (int i = 0; i < 7; i++) {
            if (i != 4 && i != 5) {
                sheet.autoSizeColumn(i);
            } else {
                sheet.setColumnWidth(i, 40 * 256);
            }
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "All_Vendor_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

// Helper
    private void appendDeptStatus(StringBuilder sb, Integer flag, String label, String iconPending, String iconApproved, String iconRecycle) {

        if (flag == 0) {
            sb.append(iconPending);
        } else if (flag == 1) {
            sb.append(iconApproved);
        } else if (flag == 3) {
            sb.append(iconRecycle);
        }
        sb.append(" ").append(label).append("\n");
    }

// Helper
    private String trimTrailingNewline(String text) {
        if (text != null && text.endsWith("\n")) {
            return text.substring(0, text.length() - 1);
        }
        return text;
    }

