    public ModelAndView searchVendor1Excel(HttpServletRequest request, HttpServletResponse response) throws Exception {
        // Get the parameters from the request
        String vendor_code = request.getParameter("vendor_code");
        String vendor_name = request.getParameter("vendor_name");
        String vendor_remark = request.getParameter("vendor_remark");

        List<VendorMaster> vendorMaster = vendorMasterService.SearchByCode(vendor_code, vendor_name, vendor_remark);

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=vendor_data.xlsx");

        XSSFWorkbook workbook = new XSSFWorkbook();
        XSSFSheet sheet = workbook.createSheet("Vendor Data");

        Row header = sheet.createRow(0);
        header.createCell(0).setCellValue("Sr. No.");
        header.createCell(1).setCellValue("Vendor Code");
        header.createCell(2).setCellValue("Vendor Name");
        header.createCell(3).setCellValue("Email");
        header.createCell(4).setCellValue("Mobile No.");
        header.createCell(5).setCellValue("Vendor Type");

        // Populate the rows with vendor data
        int rowNum = 1;
        for (VendorMaster vendor : vendorMaster) {
            Row row = sheet.createRow(rowNum++);
            row.createCell(0).setCellValue(rowNum - 1); // Sr. No.
            row.createCell(1).setCellValue(vendor.getVendorRegNo()); // Vendor Code
            row.createCell(2).setCellValue(vendor.getVendorName()); // Vendor Name
            row.createCell(3).setCellValue(vendor.getVendorEmailID()); // Email
            row.createCell(4).setCellValue(vendor.getVendorMobNo()); // Mobile No.
            row.createCell(5).setCellValue(vendor.getVendorTypeId() == 1 ? "Temporary Vendor" : "Permanent Vendor"); // Vendor Type
        }

        // Write the Excel file to the response output stream
        OutputStream out = response.getOutputStream();
        workbook.write(out);
        out.close();

        return null; // No need to return a view, as the file is being downloaded
    }

