    public ModelAndView venderinfoAttachmentDelete(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        String VInformationId = request.getParameter("id");
        String fileName = request.getParameter("fileNameAttch");

        if (VInformationId != null && fileName != null) {

            VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(VInformationId));

            int vendorinvt = vendorInformation.getVendorInvitationId();
            VendorInvitation vendorin = vendorInvitationService.readById(vendorinvt);

            String vendorEmailId = vendorin.getVendorEmailId();
            String companyName = vendorin.getCompanyName();

            Map<String, String> fileMap = new HashMap<>();

            if (vendorInformation.getCompanyProof() != null) {
                fileMap.put(vendorInformation.getCompanyProof(), "COMPANY_PROOF");
            }

            if (vendorInformation.getGstinFile() != null) {
                fileMap.put(vendorInformation.getGstinFile(), "GST_FILE");
            }
            if (vendorInformation.getPanFile() != null) {
                fileMap.put(vendorInformation.getPanFile(), "PAN_FILE");
            }
            if (vendorInformation.getService_file() != null) {
                fileMap.put(vendorInformation.getService_file(), "MSME_FILE");
            }
            if (vendorInformation.getEsicFile() != null) {
                fileMap.put(vendorInformation.getEsicFile(), "ESIC_FILE");
            }
            if (vendorInformation.getPfAttachment() != null) {
                fileMap.put(vendorInformation.getPfAttachment(), "EPFO_FILE");
            }
            if (vendorInformation.getCancelCheck() != null) {
                fileMap.put(vendorInformation.getCancelCheck(), "CHECK_FILE");
            }
            if (vendorInformation.getEcc_file() != null) {
                fileMap.put(vendorInformation.getEcc_file(), "ECC_FILE");
            }
            if (vendorInformation.getFinicalAttachment1() != null) {
                fileMap.put(vendorInformation.getFinicalAttachment1(), "ATTACHMENT1_FILE");
            }
            if (vendorInformation.getFinicalAttachment2() != null) {
                fileMap.put(vendorInformation.getFinicalAttachment2(), "ATTACHMENT2_FILE");
            }
            if (vendorInformation.getFinicalAttachment3() != null) {
                fileMap.put(vendorInformation.getFinicalAttachment3(), "ATTACHMENT3_FILE");
            }
            if (vendorInformation.getCompanyProof2() != null) {
                fileMap.put(vendorInformation.getCompanyProof2(), "COMPANY_PROOFS_FILE");
            }

            String fileType = fileMap.get(fileName);

            if (fileType != null) {

                switch (fileType) {
                    case "COMPANY_PROOF":

                        String fileLocationURL = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file = new File(fileLocationURL + File.separator + fileName);
                        if (file.exists()) {
                            file.delete();
                        }
                        vendorInformation.setCompanyProof(null);
                        break;

                    case "COMPANY_PROOFS_FILE":
                        String fileLocationURL99 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file99 = new File(fileLocationURL99 + File.separator + fileName);
                        if (file99.exists()) {
                            file99.delete();
                        }
                        vendorInformation.setCompanyProof2(null);
                        break;

                    case "GST_FILE":

                        String fileLocationURL1 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file1 = new File(fileLocationURL1 + File.separator + fileName);
                        if (file1.exists()) {
                            file1.delete();
                        }
                        vendorInformation.setGstinFile(null);
                        break;

                    case "PAN_FILE":
                        String fileLocationURL2 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file2 = new File(fileLocationURL2 + File.separator + fileName);
                        if (file2.exists()) {
                            file2.delete();
                        }

                        vendorInformation.setPanFile(null);
                        break;
                    case "MSME_FILE":
                        vendorInformation.setService_file(null);
                        break;

                    case "ESIC_FILE":
                        String fileLocationURL3 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file3 = new File(fileLocationURL3 + File.separator + fileName);
                        if (file3.exists()) {
                            file3.delete();
                        }

                        vendorInformation.setEsicFile(null);
                        break;

                    case "EPFO_FILE":
                        String fileLocationURL4 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file4 = new File(fileLocationURL4 + File.separator + fileName);
                        if (file4.exists()) {
                            file4.delete();
                        }

                        vendorInformation.setPfAttachment(null);
                        break;

                    case "CHECK_FILE":
                        String fileLocationURL5 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file5 = new File(fileLocationURL5 + File.separator + fileName);
                        if (file5.exists()) {
                            file5.delete();
                        }

                        vendorInformation.setCancelCheck(null);
                        break;

                    case "ECC_FILE":

                        String fileLocationURL6 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file6 = new File(fileLocationURL6 + File.separator + fileName);
                        if (file6.exists()) {
                            file6.delete();
                        }

                        vendorInformation.setEcc_file(null);
                        break;

                    case "ATTACHMENT1_FILE":
                        String fileLocationURL7 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file7 = new File(fileLocationURL7 + File.separator + fileName);
                        if (file7.exists()) {
                            file7.delete();
                        }

                        vendorInformation.setFinicalAttachment1(null);
                        break;

                    case "ATTACHMENT2_FILE":

                        String fileLocationURL8 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file8 = new File(fileLocationURL8 + File.separator + fileName);
                        if (file8.exists()) {
                            file8.delete();
                        }

                        vendorInformation.setFinicalAttachment2(null);
                        break;

                    case "ATTACHMENT3_FILE":

                        String fileLocationURL9 = getServletContext().getRealPath("/")
                                + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator;
                        File file9 = new File(fileLocationURL9 + File.separator + fileName);
                        if (file9.exists()) {
                            file9.delete();
                        }
                        vendorInformation.setFinicalAttachment3(null);
                        break;

                }

                vendorInformationService.update(vendorInformation);

                mv.setViewName("redirect:vendorInformation.htm?act=termsconditionVendorInformation" + "&vendorEmailId=" + vendorEmailId + "&companyName=" + companyName);
            }
        }

        return mv;
    }

