    public ModelAndView electricTechnicalRecyclesubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String user11 = user.getLoginName();

        String VInformationId = request.getParameter("VInformationId");

        VendorInformation vendorInformation3 = vendorInformationService.readById(Integer.parseInt(VInformationId));
        int vendorInvtId = vendorInformation3.getVendorInvitationId();

        VendorInvitation vendorInvitation = vendorInvitationService.readEmailId(user11);

        List vendorInvitationList = vendorInvitationCategoryService.readByVendorInvtlistId(vendorInvitation.getId());

        Map<String, Integer> rightsMap = new HashMap<>();

        for (Object vendorinvList : vendorInvitationList) {

            VendorInvitationCategory v = (VendorInvitationCategory) vendorinvList;
            String groupSubCategoryId = v.getGroupSubCategoryId();
            GroupSubCategory groupSubCategory = groupSubCategoryService.readById(Integer.parseInt(groupSubCategoryId));

            if (Integer.parseInt(groupSubCategory.getHr()) == 1) {
                rightsMap.put("HR", 1);
            }
            if (Integer.parseInt(groupSubCategory.getHsc()) == 1) {
                rightsMap.put("HSE", 1);
            }
            if (Integer.parseInt(groupSubCategory.getIt()) == 1) {
                rightsMap.put("IT", 1);
            }
            if (Integer.parseInt(groupSubCategory.getTechnical()) == 1) {
                rightsMap.put("TECHNICAL", 1);
            }
        }

        mv.getModelMap().put("rightsMap", rightsMap);
        mv.getModelMap().put("VInformationId", VInformationId);

        if (vendorInformation3.getTechnicalFlag() == 3) {

            MultipartHttpServletRequest multipartRequest = (MultipartHttpServletRequest) request;

            String path = getServletContext().getRealPath("/")
                    + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator + "TECHNICAL";
            File f1 = new File(path);
            boolean bool = f1.mkdir();

            List list1 = vendorInformationService.readyByElectric();
            String[] comments = request.getParameterValues("comment");
            String[] scores = request.getParameterValues("score");
            String[] attachment1 = request.getParameterValues("attachment1");
            List<MultipartFile> attachments = multipartRequest.getFiles("attachment");
            String electricId[] = request.getParameterValues("electricId");

            String[] topicNames = request.getParameterValues("topicname");
            String[] topicNames2 = request.getParameterValues("topicname2");
            String[] compulsaryFlag = request.getParameterValues("compulsaryFlag");
            String[] vendorCriteriaMasterId = request.getParameterValues("vendorCriteriaMasterId");
            String[] response1 = request.getParameterValues("response");
            String[] tremark = request.getParameterValues("tremark");

            try {
                for (int i = 0; i < scores.length; i++) {

                    String comment = comments[i];
                    String score = scores[i];
                    String electricIds = electricId[i];
                    String attachments1 = attachment1[i];
                    MultipartFile attachment = attachments.get(i);

                    String topicname = topicNames[i];
                    String topicname2 = topicNames2[i];

                    String compulsaryFlag1 = compulsaryFlag[i];

                    String attachmentName = "";
                    if (attachment != null && !attachment.isEmpty()) {
                        try {
                            String fileLocationURL = getServletContext().getRealPath("/")
                                    + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + VInformationId + File.separator + "TECHNICAL" + File.separator;
                            File photoFile = new File(fileLocationURL + attachment.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", ""));
                            attachmentName = attachment.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", "");
                            attachment.transferTo(photoFile);
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                    } else {

                        attachmentName = attachments1;
                    }
                    if (attachmentName.equals("") || attachmentName == "") {
                        attachmentName = attachments1;
                    }

                    if (electricIds.equals("0")) {

                        ElectricalContractor electric = new ElectricalContractor();
                        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(VInformationId));
                        electric.setCriteria(topicname);
                        electric.setSelectionCriteria(topicname2);
                        electric.setAttachment(attachmentName);
                        electric.setComment(comment);
                        electric.setVendorInformation(vendorInformation);
                        electric.setScore(score);
                        electric.setCompulsaryFlag(compulsaryFlag1);
                        electric.setVendorCriteriaMasterId(Integer.parseInt(vendorCriteriaMasterId[i]));
                        electricalContractorService.create(electric);
                    } else {
                        ElectricalContractor electric = electricalContractorService.readById(Integer.parseInt(electricIds));
                        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(VInformationId));
                        electric.setCriteria(topicname);
                        electric.setSelectionCriteria(topicname2);
                        electric.setAttachment(attachmentName);
                        electric.setComment(comment);
                        electric.setVendorInformation(vendorInformation);
                        electric.setScore(score);
                        electric.setCompulsaryFlag(compulsaryFlag1);
                        electricalContractorService.update(electric);
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
            LocalDateTime myDateObj = LocalDateTime.now();
            DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
            String formattedDate = myDateObj.format(myFormatObj);

            vendorInformation3.setTechnicalFlag(0);
            vendorInformationService.update(vendorInformation3);
            String comment1 = request.getParameter("comments");
            VendorApproval vendorApproval1 = new VendorApproval();
            vendorApproval1.setDescription(comment1);
            vendorApproval1.setActivity("Vendor Update Technical Details");
            vendorApproval1.setVendorInformationId(Integer.parseInt(VInformationId));
            vendorApproval1.setUserId(user11);
            vendorApproval1.setUserRole("Vendor");
            vendorApproval1.setDateTime(formattedDate);
            vendorApprovalService.create(vendorApproval1);
            ///////////////////Email ///////////////////////////
            String supplyer_name = vendorInformation3.getCompanyName();
            String tech_name = vendorInformation3.getTechnicalApproval();
            String email = vendorInformation3.getVendorEmailId();
            // Mail send to vendor for recycle
            String mailFrom = "samir@bulwarks.com";
            String mailTo = email;
            String subject = "Vendor Updated Technical Details";

            EmailTemplate emailTemplate = new EmailTemplate();
            emailTemplate = emailTemplateService.readById(84);
            String msg = "";
            msg = emailTemplate.getBodytext();
            msg = msg.replaceAll("\\{tech_name\\}", tech_name);
            msg = msg.replaceAll("\\{supplyer_name\\}", supplyer_name);
            msg = msg.replaceAll("\\{comment\\}", comment1);

            SendMail mailSender = new SendMail();
            mailSender.sendMail(mailFrom, mailTo, subject, msg);
            List list6 = vendorHrCriteriaService.readByGroupName(vendorInvtId + "");
            List list66 = vendorHrCriteriaCommentService.readByVendorInformationId(VInformationId);

            mv.getModelMap().put("list6", list6);
            mv.getModelMap().put("list66", list66);
            session.setAttribute("successMessage", "Vendor Technical information has been successfully updated and submitted.");
        } else {
            session.setAttribute("failureMessage", "Vendor Technical Information Already has been successfully updated and submitted.");
        }
        mv.setViewName("redirect:vendorInformation.htm?act=electricTechnicalRecycle");
        return mv;

    }

