    public ModelAndView ButtonSafetyApprovals(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        HttpSession session = request.getSession();
        UserMaster user = (UserMaster) session.getAttribute("user");
        String user11 = user.getLoginName();

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);

        String id = request.getParameter("id");
        String comment = request.getParameter("comment");

        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(id));
        int safetyFlag = vendorInformation.getSafteyApprovalFlag();

        if (safetyFlag == 0) {

            EmployeeMaster employeeMaster8 = employeeMasterService.readUser(user11);
            String role = employeeMaster8.getDesignation();

            vendorInformation.setSafteyApprovalFlag(1);
            vendorInformationService.update(vendorInformation);

            String safetyId[] = request.getParameterValues("safetyId");
            String accept[] = request.getParameterValues("accept");
            String remark[] = request.getParameterValues("remark");
            String safetyComment[] = request.getParameterValues("safetyComment");

            int a = 0;
            for (String s : safetyId) {
                VendorSafetyCriteriaComment vendorSafetyCriteriaComment = vendorSafetyCriteriaCommentService.readById(Integer.parseInt(s));
                vendorSafetyCriteriaComment.setAccept(Integer.parseInt(accept[a]));
                vendorSafetyCriteriaComment.setRemark(remark[a]);
                if ("1".equals(accept[a]) || "2".equals(accept[a])) {
                    vendorSafetyCriteriaComment.setSafetyComment("");
                } else {
                    vendorSafetyCriteriaComment.setSafetyComment(safetyComment[a]);
                }
                vendorSafetyCriteriaCommentService.update(vendorSafetyCriteriaComment);
                a++;

            }

            VendorApproval vendorApproval1 = new VendorApproval();
            vendorApproval1.setDescription(comment);
            vendorApproval1.setActivity("Saftey Accept");
            vendorApproval1.setVendorInformationId(Integer.parseInt(id));
            vendorApproval1.setUserId(user11);
            vendorApproval1.setDateTime(formattedDate);
            vendorApproval1.setUserRole(role);
            vendorApprovalService.create(vendorApproval1);

            ////////////////Final Approval////////////////////
            VendorInformation vendorInformation1 = vendorInformationService.readById(Integer.parseInt(id));
            int techflg = vendorInformation1.getTechnicalFlag();
            int finaflag = vendorInformation1.getFinacialFlag();
            int hrflag = vendorInformation1.getHrApprovalFlag();
            int itflag = vendorInformation1.getItApprovalFlag();
            int saftflag = vendorInformation1.getSafteyApprovalFlag();
            int auditorFlag = vendorInformation1.getAuditorFlag();
            int buyer_status = vendorInformation1.getStatus1();

            if (techflg == 1 && finaflag == 1 && saftflag == 1 && hrflag == 1 && itflag == 1 && buyer_status == 2 && auditorFlag == 1) {

                vendorInformation1.setStatus1(500);
                vendorInformationService.update(vendorInformation1);

                try {
                    EmailTemplate emailTemplate4 = new EmailTemplate();
                    emailTemplate4 = emailTemplateService.readById(196);

                    String buyerEmail = vendorInformation1.getVendorEmailId();
                    String mailFrom4 = "samir@bulwarks.com";
                    String mailTo4 = buyerEmail;
                    String subject4 = emailTemplate4.getSubject();
                    String msg4 = "";
                    msg4 = emailTemplate4.getBodytext();
                    msg4 = msg4.replaceAll("\\{vendor_name\\}", vendorInformation1.getCompanyName());
                    msg4 = msg4.replaceAll("\\{vendor_id\\}", vendorInformation1.getVendorEmailId());
                    msg4 = msg4.replaceAll("\\{date\\}", formattedDate);

                    SendMail mailSender4 = new SendMail();
                    mailSender4.sendMail(mailFrom4, mailTo4, subject4, msg4);
                } catch (Exception e) {

                }
                VendorRecycleMailScheduler vendorRecycleMailScheduler1 = vendorRecycleMailSchedulerService.readByInfoId(Integer.parseInt(id));
                vendorRecycleMailScheduler1.setDateTime(formattedDate);
                vendorRecycleMailSchedulerService.update(vendorRecycleMailScheduler1);
            }

            session.setAttribute("successMessage", "This vendor record has Approved by the HSE Team.");

        } else if (safetyFlag == 3) {

            session.setAttribute("failureMessage", "This vendor record has already been Recycle by the HSE Team.");

        } else if (safetyFlag == 1) {

            session.setAttribute("failureMessage", "This vendor record has already been Approved by the HSE Team.");

        } else {

            session.setAttribute("failureMessage", "This vendor record has already moved to next process of approval.");

        }

        mv.setViewName("redirect:vendorInformation.htm?act=safetyApproval");
        return mv;
    }

