    public ModelAndView complianceOfficerAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        int draw = Integer.parseInt(request.getParameter("draw"));
        int start = Integer.parseInt(request.getParameter("start"));
        int length = Integer.parseInt(request.getParameter("length"));

        String searchValue = request.getParameter("search[value]");

        String orderColumnIndex = request.getParameter("order[0][column]");
        String orderDir = request.getParameter("order[0][dir]");

        if (orderDir == null || orderDir.equals("")) {
            orderDir = "desc";
        }

        if (orderColumnIndex == null || orderColumnIndex.equals("")) {
            orderColumnIndex = "0";
        }

        String orderColumn = "id";

        if (orderColumnIndex != null) {

            switch (Integer.parseInt(orderColumnIndex)) {

                case 0:
                    orderColumn = "id";
                    break;
                case 1:
                    orderColumn = "companyName";
                    break;
                case 2:
                    orderColumn = "vendorEmailId";
                    break;
                default:
                    orderColumn = "id";
            }
        }

        List complianceOfficerList = vendorInformationService.getComplianceOfficerPagination(start, length, orderColumn, orderDir, searchValue);

        int recordsTotalComplianceOfficer = vendorInformationService.getAllComplianceOfficerCount();

        int recordsFilteredComplianceOfficer = vendorInformationService.getFilteredComplianceOfficerCount(searchValue);

        List data = new ArrayList();

        boolean isDesc = "desc".equalsIgnoreCase(orderDir);

        int srNo;

        if (isDesc) {
            srNo = recordsFilteredComplianceOfficer - start;
        } else {
            srNo = start + 1;
        }

        for (Iterator it = complianceOfficerList.iterator(); it.hasNext();) {

            Object[] row = (Object[]) it.next();

            Map map = new HashMap();

            if (isDesc) {
                map.put("srNo", srNo--);
            } else {
                map.put("srNo", srNo++);
            }

            map.put("companyName", row[1] != null ? row[1] : "");

            map.put("vendorEmailId", row[2] != null ? row[2] : "");

            Integer status = row[3] != null ? Integer.parseInt(row[3].toString()) : null;

            String statusText = "";

            if (status != null) {
                if (status == 500) {
                    statusText = "Pending";
                } else if (status == 502) {
                    statusText = "Recycle";
                } else if (status == 501) {
                    statusText = "Reject";
                } else if (status == 10) {
                    statusText = "Active Vender";
                }
            }

            map.put("status", statusText);

            String vendorId = row[0] != null ? row[0].toString() : "";

            String actionHtml;

            if (status != null && status == 500) {
                actionHtml = "<button type='button' class='btn theme-btn' "
                        + "id='loginName" + srNo + "' value='" + vendorId + "' "
                        + "data-toggle='dropdown' aria-haspopup='true' aria-expanded='false' "
                        + "onclick=\"viewClickss1('" + vendorId + "');\">"
                        + "&nbsp;View And Approve"
                        + "</button>";
            } else {
                actionHtml = "<button type='button' class='btn theme-btn light-btn' "
                        + "id='loginName" + srNo + "' value='" + vendorId + "' "
                        + "data-toggle='dropdown' aria-haspopup='true' aria-expanded='false' "
                        + "onclick=\"viewClickss('" + vendorId + "');\">"
                        + "&nbsp;View"
                        + "</button>";
            }
            map.put("action", actionHtml);

            data.add(map);
        }

        JSONObject json = new JSONObject();

        json.put("draw", draw);
        json.put("recordsTotal", recordsTotalComplianceOfficer);
        json.put("recordsFiltered", recordsFilteredComplianceOfficer);
        json.put("data", data);

        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");

        response.getWriter().write(json.toString());

        return null;

    }

    public void complianceOfficerExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }

        String searchValue = request.getParameter("searchValue") != null ? request.getParameter("searchValue") : "";

        String orderColumn = "id";
        String orderDir = "desc";

        int start = 0;
        int filteredRecords = vendorInformationService.getFilteredComplianceOfficerCount(searchValue);

        List complianceOfficerList = vendorInformationService.getComplianceOfficerPagination(start, filteredRecords, orderColumn, orderDir, searchValue);

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("Compliance Officer Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        int rowNum = 0;
        int srNo = 1;

        sheet.createFreezePane(0, 1);

        Row headerRow = sheet.createRow(rowNum++);

        String[] headers = {
            "Sr.No.", "Company Name", "Email Id", "Status"
        };

        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        CellStyle hyperlinkStyle = workbook.createCellStyle();
        Font hyperlinkFont = workbook.createFont();
        hyperlinkFont.setUnderline(Font.U_SINGLE);
        hyperlinkFont.setColor(IndexedColors.BLUE.getIndex());
        hyperlinkStyle.setFont(hyperlinkFont);

        for (Iterator it = complianceOfficerList.iterator(); it.hasNext();) {

            Object[] row = (Object[]) it.next();

            String companyName = row[1] != null ? row[1].toString() : "";
            String vendorEmailId = row[2] != null ? row[2].toString() : "";

            Integer status = row[3] != null ? Integer.parseInt(row[3].toString()) : null;

            String statusText = "";

            if (status != null) {
                if (status == 500) {
                    statusText = "Pending";
                } else if (status == 502) {
                    statusText = "Recycle";
                } else if (status == 501) {
                    statusText = "Reject";
                } else if (status == 10) {
                    statusText = "Active Vender";
                }
            }

            Row excelRow = sheet.createRow(rowNum++);
            excelRow.setHeightInPoints(60);

            excelRow.createCell(0).setCellValue(srNo++);
            excelRow.createCell(1).setCellValue(companyName);
            excelRow.createCell(2).setCellValue(vendorEmailId);
            excelRow.createCell(3).setCellValue(statusText);

        }

        for (int i = 0; i < headers.length; i++) {
            sheet.autoSizeColumn(i);
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "Compliance_Officer_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

