    public ModelAndView ComplianceOfficerApproved(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        HttpSession session = request.getSession(false);
        UserMaster user1 = (UserMaster) session.getAttribute("user");
        String username1 = user1.getLoginName();

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);

        String id = request.getParameter("id");
        String comment = request.getParameter("comment");

        VendorInformation venInformation = vendorInformationService.readById(Integer.parseInt(id));
        int status1 = venInformation.getStatus1();

        if (status1 == 500) {

            venInformation.setStatus1(10);
            venInformation.setVendorActivatedDate(formattedDate);
            vendorInformationService.update(venInformation);

            EmployeeMaster employeeMaster8 = employeeMasterService.readUser(username1);
            String role = employeeMaster8.getDesignation();

            VendorApproval vendorApproval = new VendorApproval();
            vendorApproval.setActivity("Compliance Officer Approved");
            vendorApproval.setDescription(comment);
            vendorApproval.setUserId(username1);
            vendorApproval.setDateTime(formattedDate);
            vendorApproval.setVendorInformationId(Integer.parseInt(id));
            vendorApproval.setUserRole(role);
            vendorApprovalService.create(vendorApproval);

            VendorMaster vendorMaster = vendorMasterService.readByRegNo(venInformation.getVendorEmailId());
            vendorMaster.setFlag(1);
            vendorMaster.setVendorAddressLine1(venInformation.getOfficeAddressLine1());
            vendorMaster.setVendorAddressLine2(venInformation.getOfficeAddressLine2());
            vendorMaster.setVendorAddressLine3(venInformation.getOfficeAddressLine3());
            vendorMaster.setVendorCity(venInformation.getOfficeCity());
            vendorMaster.setVendorCountry(venInformation.getOfficeCountry());
            vendorMaster.setVendorDistrict(venInformation.getOfficeDistrict());
            vendorMaster.setVendorState(venInformation.getOfficeState());
            vendorMaster.setVendorPincode(venInformation.getOfficePin());
            vendorMaster.setVendorMobNo(venInformation.getOfficeTelephone());
            vendorMaster.setVendorcc(venInformation.getEmail1());
            vendorMasterService.update(vendorMaster);

            VendorRecycleMailScheduler vendorRecycleMailScheduler = vendorRecycleMailSchedulerService.readByInfoId(Integer.parseInt(id));
            vendorRecycleMailScheduler.setDateTime(formattedDate);
            vendorRecycleMailScheduler.setApprovalStatus("1");
            vendorRecycleMailSchedulerService.update(vendorRecycleMailScheduler);

            session.setAttribute("successMessage", "This vendor record has Approved by Compliance Officer.");
        } else if (status1 == 502) {

            session.setAttribute("failureMessage", "This vendor record has already been Recycled by Compliance Officer.");
        } else if (status1 == 501) {

            session.setAttribute("failureMessage", "This vendor record has already been Reject by Compliance Officer.");

        } else if (status1 == 10) {

            session.setAttribute("failureMessage", "This vendor has already been Activated.");

        } else {

            session.setAttribute("failureMessage", "This vendor record has already moved to next process of approval.");

        }

        mv.setViewName("redirect:vendorInformation.htm?act=ComplianceOfficer");
        return mv;
    }

