    public ModelAndView vendorDetailsDocxdownloadzip(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id1 = request.getParameter("id1");

        VendorInformation vendorinfo = vendorInformationService.readById(Integer.parseInt(id1));

        String file1 = vendorinfo.getPolicy1File();
        String file2 = vendorinfo.getNdaPolicyFile();
        String file3 = vendorinfo.getCompanyProof();

        String[] fileNames = new String[]{file1, file2, file3};

        response.setContentType("application/zip");
        response.setHeader("Content-Disposition", "attachment;filename=VENDORDETAILSFILEFOR" + vendorinfo.getCompanyName() + ".zip");

        try (ZipOutputStream zos = new ZipOutputStream(response.getOutputStream())) {

            for (String fileEntry : fileNames) {

                if (fileEntry == null || fileEntry.trim().equals("")) {
                    continue;
                }

                String fileLocationURL = request.getServletContext().getRealPath("/")
                        + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + id1 + File.separator;

                String fileLocation = fileLocationURL + fileEntry;

                File file = new File(fileLocation);

                if (file.exists()) {
                    try (FileInputStream fis = new FileInputStream(file)) {

                        ZipEntry zipEntry = new ZipEntry(fileEntry);

                        try {
                            zos.putNextEntry(zipEntry);

                            byte[] buffer = new byte[1024];
                            int length;
                            while ((length = fis.read(buffer)) > 0) {
                                zos.write(buffer, 0, length);
                            }

                            zos.closeEntry();

                        } catch (IOException duplicateFileException) {
                            System.err.println("Skipping duplicate file: " + fileEntry);
                        }

                    } catch (IOException fileReadException) {
                        System.err.println("Error reading file: " + fileEntry);
                    }

                } else {
                    System.err.println("File not found: " + fileLocation);
                }
            }

        } catch (IOException e) {
            e.printStackTrace();
        }

        return mv;

    }

