    public ModelAndView VendorActiveProfileViewPrint(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        VendorSafetyCriteriaComment vendorSafetyCriteriaComment = new VendorSafetyCriteriaComment();

        HttpSession session = request.getSession();
        UserMaster user = (UserMaster) session.getAttribute("user");
        String user11 = user.getLoginName();
        if (user.getUserType() == 2) {
            user11 = user.getVendorCode();
        }
        VendorInvitation vendorInvitation = vendorInvitationService.readEmailId(user11);

        VendorInformation vendorInformation = vendorInformationService.readEmailId(user11);
        int vendorInvtId = vendorInformation.getVendorInvitationId();

        List vendorInvitationList = vendorInvitationCategoryService.readByVendorInvtlistId(vendorInvtId);

        Map<String, Integer> rightsMap = new HashMap<>();

        for (Object vendorinvList : vendorInvitationList) {

            VendorInvitationCategory v = (VendorInvitationCategory) vendorinvList;
            String groupSubCategoryId = v.getGroupSubCategoryId();
            GroupSubCategory groupSubCategory = groupSubCategoryService.readById(Integer.parseInt(groupSubCategoryId));

            // Now check each field and update the map if 1 is found
            if (Integer.parseInt(groupSubCategory.getHr()) == 1) {
                rightsMap.put("HR", 1);
            }
            if (Integer.parseInt(groupSubCategory.getHsc()) == 1) {
                rightsMap.put("HSE", 1);
            }
            if (Integer.parseInt(groupSubCategory.getIt()) == 1) {
                rightsMap.put("IT", 1);
            }
            if (Integer.parseInt(groupSubCategory.getTechnical()) == 1) {
                rightsMap.put("TECHNICAL", 1);
            }
        }

        mv.getModelMap().put("rightsMap", rightsMap);

        int VInformationId = vendorInformation.getId();
        List list4 = electricalContractorService.readByVendorInformationId(VInformationId + "");
        List list5 = vendorHrCriteriaCommentService.readByVendorInformationId(VInformationId + "");
        List list6 = vendorSafetyCriteriaCommentService.readByVendorInformationId(VInformationId + "");
        List list9 = vendorItCriteriaCommentService.readByVendorInformationId(VInformationId + "");
        List list7 = vendorInvitationCategoryService.readIds(vendorInvtId);

        mv.getModelMap().put("list7", list7);
        List list8 = vendorInvitationCategoryService.readByAll(vendorInvtId);
        VendorSelfDeclaration declaration = vendorSelfDeclarationService.readByVendorInformationId(VInformationId);
        mv.getModelMap().put("declaration", declaration);
        List vendorApproval1 = vendorApprovalService.readId(VInformationId);
        request.setAttribute("vendorApproval", vendorApproval1);

        mv.getModelMap().put("list8", list8);

        List mplist = managerialPersonService.readInvitationId(vendorInvtId);
        mv.getModelMap().put("mplist", mplist);

        List lstwork = lastWorkExpDeatilsService.readByVendorinvitId(VInformationId);
        mv.getModelMap().put("lstwork", lstwork);

        mv.getModelMap().put("vendorInvitation", vendorInvitation);
        mv.getModelMap().put("vendorInformation", vendorInformation);
        mv.getModelMap().put("VInformationId", VInformationId);
        mv.getModelMap().put("list4", list4);
        mv.getModelMap().put("list5", list5);
        mv.getModelMap().put("list6", list6);
        mv.getModelMap().put("list9", list9);
        mv.setViewName("Vendor/VendorActiveProfileViewPrint");
        return mv;
    }

