    public ModelAndView vendorBlock(HttpServletRequest request, HttpServletResponse response) throws Exception {

        ModelAndView mv = new ModelAndView();
        HttpSession session1 = request.getSession(false);
        UserMaster user1 = (UserMaster) session1.getAttribute("user");
        String username1 = user1.getLoginName();

        SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");

        String today = dateFormat.format(new Date());

        java.text.SimpleDateFormat formatter5 = new java.text.SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
        String currentDateTime5 = formatter5.format(new java.util.Date());

        String id = request.getParameter("id");
        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(id));

        String remark = request.getParameter("remark");

        VendorBlockList vendorBlockList = new VendorBlockList();

        if (request instanceof MultipartHttpServletRequest) {
            MultipartHttpServletRequest multipartRequest = (MultipartHttpServletRequest) request;

            MultipartFile attachment = multipartRequest.getFile("attachment");

            String attachmentFileName = "";

            if (attachment != null && !attachment.isEmpty()) {
                attachmentFileName = attachment.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", "");

                String fileLocationURL = getServletContext().getRealPath("/")
                        + File.separator + "StorageYard" + File.separator + "UserProfile"
                        + File.separator + "Vendor" + File.separator + vendorInformation.getId() + File.separator;

                File directory = new File(fileLocationURL);
                if (!directory.exists()) {
                    directory.mkdirs();
                }

                File destinationFile = new File(fileLocationURL + attachmentFileName);
                attachment.transferTo(destinationFile);

                vendorBlockList.setAttchment(attachmentFileName);
            }
        }

        vendorBlockList.setVendorInfoId(Integer.parseInt(id));
        vendorBlockList.setComments(remark);
        vendorBlockList.setFlagStatus(700); //blocked
        vendorInformation.setStatus1(700); //blocked
        vendorBlockList.setUserName(username1);
        vendorBlockList.setDateTime(currentDateTime5);
        vendorBlockListService.create(vendorBlockList);
        vendorInformationService.update(vendorInformation);

        String requestedWith = request.getHeader("X-Requested-With");

        if ("XMLHttpRequest".equals(requestedWith)) {

            response.setContentType("text/plain");
            response.setCharacterEncoding("UTF-8");
            response.getWriter().write("SUCCESS");
            response.getWriter().flush();
            return null;
        }

        session1.setAttribute("successMessage", "Vendor blocked successfully");
        mv.setViewName("redirect:vendorInformation.htm?act=activeVendor");

        return mv;

    }

