    public ModelAndView FinancialDetailsChangeProcess(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        String id = request.getParameter("id");
        String remark = request.getParameter("remark");

        SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");
        String today = dateFormat.format(new Date());
        java.text.SimpleDateFormat formatter5 = new java.text.SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
        String currentDateTime5 = formatter5.format(new java.util.Date());

        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(id));

        vendorInformation.setVendorCommentForBuyer(remark);
        vendorInformation.setFinacialFlag(5);
        try {
            EmployeeMaster employeeMaster2 = employeeMasterService.readByEmployeeName(vendorInformation.getApprovalOne());
            String mail_to = employeeMaster2.getEmailId();
            EmailTemplate emailTemplate = emailTemplateService.readById(202);
            String mail_from = "";
            String subject = emailTemplate.getSubject();
            String msg = emailTemplate.getBodytext();
            String vendor_finacial = "Vendor Financial Details Change Process";
            msg = msg.replaceAll("\\{vendor_finacial\\}", vendor_finacial);
            msg = msg.replaceAll("\\{remark\\}", remark);
            msg = msg.replaceAll("\\{username\\}", vendorInformation.getCompanyName());
            msg = msg.replaceAll("\\{createddate\\}", currentDateTime5);
            SendMail s1 = new SendMail();
            s1.sendMail(mail_from, mail_to, subject, msg);
        } catch (Exception e) {
            e.printStackTrace();
        }
        VendorApproval vendorApproval = new VendorApproval();
        vendorApproval.setDateTime(currentDateTime5);
        vendorApproval.setDescription(remark);
        vendorApproval.setUserId(vendorInformation.getVendorEmailId());
        vendorApproval.setActivity("Vendor Financial Details Change Request Sent");
        vendorApproval.setUserRole("Vendor");
        vendorApproval.setVendorInformationId(Integer.parseInt(id));

        vendorApprovalService.create(vendorApproval);

        vendorInformationService.update(vendorInformation);

        out.print("{\"status\":\"success\"}");
        out.flush();

        return null;
    }

    private String generateUniqueFileNameAndCopy(String currentFileName, List<String> existingNames, String vendorId) {

        if (currentFileName == null || currentFileName.isEmpty()) {
            return currentFileName;
        }

        String uniqueFileName = currentFileName;

        try {
            String baseName = currentFileName;
            String extension = "";
            int dotIndex = currentFileName.lastIndexOf(".");
            if (dotIndex != -1) {
                baseName = currentFileName.substring(0, dotIndex);
                extension = currentFileName.substring(dotIndex);
            }

            // ---- STEP 1: strip any trailing 2-digit suffix to get the true "root" name ----
            String rootName = baseName;
            if (rootName.length() > 2 && rootName.substring(rootName.length() - 2).matches("\\d{2}")) {
                rootName = rootName.substring(0, rootName.length() - 2);
            }

            // ---- STEP 2: scan history for the same root, find the highest counter already used ----
            boolean rootPlainExists = false;
            int maxCounter = -1;

            if (existingNames != null) {
                for (String name : existingNames) {
                    if (name == null) {
                        continue;
                    }

                    String nBase = name;
                    String nExt = "";
                    int nDot = name.lastIndexOf(".");
                    if (nDot != -1) {
                        nBase = name.substring(0, nDot);
                        nExt = name.substring(nDot);
                    }

                    if (!nExt.equalsIgnoreCase(extension)) {
                        continue;
                    }

                    if (nBase.equals(rootName)) {
                        rootPlainExists = true;
                    } else if (nBase.length() == rootName.length() + 2 && nBase.startsWith(rootName)) {
                        String suffix = nBase.substring(rootName.length());
                        if (suffix.matches("\\d{2}")) {
                            int c = Integer.parseInt(suffix);
                            if (c > maxCounter) {
                                maxCounter = c;
                            }
                        }
                    }
                }
            }

            // ---- STEP 3: decide the final unique name ----
            String finalName;
            if (!rootPlainExists && maxCounter == -1) {
                // never used before at all -> keep clean root name, no suffix
                finalName = rootName + extension;
            } else {
                int nextCounter = maxCounter + 1;
                if (nextCounter < 1) {
                    nextCounter = 1;
                }
                finalName = rootName + String.format("%02d", nextCounter) + extension;
            }

            uniqueFileName = finalName;

            // ---- STEP 4: copy the physical file to the final name if it's actually different ----
            if (!finalName.equals(currentFileName)) {

                String fileLocationURL = getServletContext().getRealPath("/")
                        + File.separator + "StorageYard" + File.separator + "UserProfile" + File.separator + "Vendor" + File.separator + vendorId + File.separator;

                File directory = new File(fileLocationURL);
                if (!directory.exists()) {
                    directory.mkdirs();
                }

                File originalFile = new File(fileLocationURL + currentFileName);
                File destinationFile = new File(fileLocationURL + finalName);

                if (originalFile.exists()) {
                    java.nio.file.Files.copy(originalFile.toPath(), destinationFile.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
                } else {
                    System.out.println("Original file not found at: " + originalFile.getAbsolutePath());
                }
            }

        } catch (Exception e) {
            uniqueFileName = currentFileName;
            e.printStackTrace();
        }

        return uniqueFileName;
    }

    public ModelAndView FinancialApprovalProcess(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        String id = request.getParameter("id");
        String remark = request.getParameter("remark");
        String approvalStatus = request.getParameter("approvalStatus");

        java.text.SimpleDateFormat formatter5 = new java.text.SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
        String currentDateTime5 = formatter5.format(new java.util.Date());

        VendorInformation vendorInformation = vendorInformationService.readById(Integer.parseInt(id));

        vendorInformation.setBuyerCommentForApproval(remark);

        int financialFlagValue = 0;
        if ("Approve".equals(approvalStatus)) {
            financialFlagValue = 6;

            VendorFinancialDetailsHistory vendorFinancialDetailsHistory = new VendorFinancialDetailsHistory();

            vendorFinancialDetailsHistory.setVendorInfoId(Integer.parseInt(id));
            vendorFinancialDetailsHistory.setDateTime(currentDateTime5);
            vendorFinancialDetailsHistory.setGsntNo(vendorInformation.getGstinNo());
            vendorFinancialDetailsHistory.setPanNo(vendorInformation.getPanNo());
            vendorFinancialDetailsHistory.setMsmeNo(vendorInformation.getService_tax());
            vendorFinancialDetailsHistory.setMsmeStatus(vendorInformation.getMsmeStatus());
            vendorFinancialDetailsHistory.setEsicNo(vendorInformation.getEsicNo());
            vendorFinancialDetailsHistory.setEsicStatus(vendorInformation.getEsicStatus());
            vendorFinancialDetailsHistory.setEpfoNo(vendorInformation.getPfNo());
            vendorFinancialDetailsHistory.setEpfoStatus(vendorInformation.getEpfoStatus());
            vendorFinancialDetailsHistory.setIecNo(vendorInformation.getEcc_no());
            vendorFinancialDetailsHistory.setIecStatus(vendorInformation.getEccStatus());
            vendorFinancialDetailsHistory.setAccountNo(vendorInformation.getAccountNumber());
            vendorFinancialDetailsHistory.setBranchName(vendorInformation.getBranch());
            vendorFinancialDetailsHistory.setBankName(vendorInformation.getBankName());
            vendorFinancialDetailsHistory.setIfscCode(vendorInformation.getIfscCode());
            vendorFinancialDetailsHistory.setSwiftCode(vendorInformation.getSwiftCode());
            vendorFinancialDetailsHistory.setFinacialYearOne(vendorInformation.getFinical1());
            vendorFinancialDetailsHistory.setFinacialYearAmountOne(vendorInformation.getFinicalAmount1());
            vendorFinancialDetailsHistory.setFinacialYearTwo(vendorInformation.getFinical2());
            vendorFinancialDetailsHistory.setFinacialYearAmountTwo(vendorInformation.getFinicalAmount2());
            vendorFinancialDetailsHistory.setFinacialYearThree(vendorInformation.getFinical3());
            vendorFinancialDetailsHistory.setFinacialYearAmountThree(vendorInformation.getFinicalAmount3());
            vendorFinancialDetailsHistory.setHistoryComment(vendorInformation.getVendorCommentForBuyer());

            List historyList = vendorFinancialDetailsHistoryService.readByVendorinfoIds(vendorInformation.getId());

            // ---- decide revision number FIRST ----
            String revisionNo = "R0";
            boolean isFirstRevision = (historyList == null || historyList.isEmpty());

            if (!isFirstRevision) {
                VendorFinancialDetailsHistory lastHistory = (VendorFinancialDetailsHistory) historyList.get(historyList.size() - 1);
                String history = lastHistory.getHistory();
                if (history != null && history.matches("R\\d+")) {
                    int revision = Integer.parseInt(history.substring(1));
                    revisionNo = "R" + (revision + 1);
                }
            }

            // ---- current file names from vendorInformation ----
            String gstFile = vendorInformation.getGstinFile();
            String panFile = vendorInformation.getPanFile();
            String msmeFile = vendorInformation.getService_file();
            String Esic = vendorInformation.getEsicFile();
            String Epfo = vendorInformation.getPfAttachment();
            String iec = vendorInformation.getEcc_file();
            String cancelcheck = vendorInformation.getCancelCheck();
            String firstYearFile = vendorInformation.getFinicalAttachment1();
            String secondYearFile = vendorInformation.getFinicalAttachment2();
            String thirdYearFile = vendorInformation.getFinicalAttachment3();

            if (isFirstRevision) {
                // ---- R0: store file names AS-IS, no increment logic at all ----
                vendorFinancialDetailsHistory.setGstFile(gstFile);
                vendorFinancialDetailsHistory.setPanFile(panFile);
                vendorFinancialDetailsHistory.setMsmeFile(msmeFile);
                vendorFinancialDetailsHistory.setEsicFile(Esic);
                vendorFinancialDetailsHistory.setEpfoFile(Epfo);
                vendorFinancialDetailsHistory.setIecFile(iec);
                vendorFinancialDetailsHistory.setCancelCheck(cancelcheck);
                vendorFinancialDetailsHistory.setFinacialYearFileOne(firstYearFile);
                vendorFinancialDetailsHistory.setFinacialYearFileTwo(secondYearFile);
                vendorFinancialDetailsHistory.setFinacialYearFileThree(thirdYearFile);

            } else {
                // ---- R1 onwards: apply increment logic based on history ----

                List<String> existingGstFileNames = new java.util.ArrayList<String>();
                List<String> existingPanFileNames = new java.util.ArrayList<String>();
                List<String> existingMsmeFileNames = new java.util.ArrayList<String>();
                List<String> existingEsicFileNames = new java.util.ArrayList<String>();
                List<String> existingEpfoFileNames = new java.util.ArrayList<String>();
                List<String> existingIecFileNames = new java.util.ArrayList<String>();
                List<String> existingCancelCheckNames = new java.util.ArrayList<String>();
                List<String> existingFirstYearFileNames = new java.util.ArrayList<String>();
                List<String> existingSecondYearFileNames = new java.util.ArrayList<String>();
                List<String> existingThirdYearFileNames = new java.util.ArrayList<String>();

                for (Object obj : historyList) {
                    VendorFinancialDetailsHistory h = (VendorFinancialDetailsHistory) obj;
                    if (h.getGstFile() != null) {
                        existingGstFileNames.add(h.getGstFile());
                    }
                    if (h.getPanFile() != null) {
                        existingPanFileNames.add(h.getPanFile());
                    }
                    if (h.getMsmeFile() != null) {
                        existingMsmeFileNames.add(h.getMsmeFile());
                    }
                    if (h.getEsicFile() != null) {
                        existingEsicFileNames.add(h.getEsicFile());
                    }
                    if (h.getEpfoFile() != null) {
                        existingEpfoFileNames.add(h.getEpfoFile());
                    }
                    if (h.getIecFile() != null) {
                        existingIecFileNames.add(h.getIecFile());
                    }
                    if (h.getCancelCheck() != null) {
                        existingCancelCheckNames.add(h.getCancelCheck());
                    }
                    if (h.getFinacialYearFileOne() != null) {
                        existingFirstYearFileNames.add(h.getFinacialYearFileOne());
                    }
                    if (h.getFinacialYearFileTwo() != null) {
                        existingSecondYearFileNames.add(h.getFinacialYearFileTwo());
                    }
                    if (h.getFinacialYearFileThree() != null) {
                        existingThirdYearFileNames.add(h.getFinacialYearFileThree());
                    }
                }

                String uniqueGstFile = generateUniqueFileNameAndCopy(gstFile, existingGstFileNames, id);
                String uniquePanFile = generateUniqueFileNameAndCopy(panFile, existingPanFileNames, id);
                String uniqueMsmeFile = generateUniqueFileNameAndCopy(msmeFile, existingMsmeFileNames, id);
                String uniqueEsic = generateUniqueFileNameAndCopy(Esic, existingEsicFileNames, id);
                String uniqueEpfo = generateUniqueFileNameAndCopy(Epfo, existingEpfoFileNames, id);
                String uniqueIec = generateUniqueFileNameAndCopy(iec, existingIecFileNames, id);
                String uniqueCancelCheck = generateUniqueFileNameAndCopy(cancelcheck, existingCancelCheckNames, id);
                String uniqueFirstYearFile = generateUniqueFileNameAndCopy(firstYearFile, existingFirstYearFileNames, id);
                String uniqueSecondYearFile = generateUniqueFileNameAndCopy(secondYearFile, existingSecondYearFileNames, id);
                String uniqueThirdYearFile = generateUniqueFileNameAndCopy(thirdYearFile, existingThirdYearFileNames, id);

                vendorFinancialDetailsHistory.setGstFile(uniqueGstFile);
                vendorFinancialDetailsHistory.setPanFile(uniquePanFile);
                vendorFinancialDetailsHistory.setMsmeFile(uniqueMsmeFile);
                vendorFinancialDetailsHistory.setEsicFile(uniqueEsic);
                vendorFinancialDetailsHistory.setEpfoFile(uniqueEpfo);
                vendorFinancialDetailsHistory.setIecFile(uniqueIec);
                vendorFinancialDetailsHistory.setCancelCheck(uniqueCancelCheck);
                vendorFinancialDetailsHistory.setFinacialYearFileOne(uniqueFirstYearFile);
                vendorFinancialDetailsHistory.setFinacialYearFileTwo(uniqueSecondYearFile);
                vendorFinancialDetailsHistory.setFinacialYearFileThree(uniqueThirdYearFile);
            }

            vendorFinancialDetailsHistory.setHistory(revisionNo);
            vendorFinancialDetailsHistoryService.create(vendorFinancialDetailsHistory);

        } else if ("Reject".equals(approvalStatus)) {
            financialFlagValue = 7;
        }

        vendorInformation.setFinacialFlag(financialFlagValue);

        try {
            String mail_to = vendorInformation.getVendorEmailId();
            EmailTemplate emailTemplate = emailTemplateService.readById(203);
            if (emailTemplate != null && mail_to != null && !mail_to.trim().isEmpty()) {
                String mail_from = "";
                String subject = emailTemplate.getSubject();
                String msg = emailTemplate.getBodytext();

                String vendor_finacial = "Vendor Buyer Details " + approvalStatus + "d";
                msg = msg.replaceAll("\\{vendor_buyer\\}", vendor_finacial);
                msg = msg.replaceAll("\\{remark\\}", remark);
                msg = msg.replaceAll("\\{username\\}", vendorInformation.getCompanyName());
                msg = msg.replaceAll("\\{createddate\\}", currentDateTime5);

                SendMail s1 = new SendMail();
                s1.sendMail(mail_from, mail_to, subject, msg);
            } else {
                System.out.println("Email skipped - template or recipient missing for id: " + id);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        VendorApproval vendorApproval = new VendorApproval();
        vendorApproval.setDateTime(currentDateTime5);
        vendorApproval.setDescription(remark);
        vendorApproval.setUserId(vendorInformation.getVendorEmailId());
        vendorApproval.setActivity("Vendor Buyer Details " + approvalStatus + "d by Buyer");
        vendorApproval.setUserRole(vendorInformation.getApprovalOne());
        vendorApproval.setVendorInformationId(Integer.parseInt(id));

        vendorApprovalService.create(vendorApproval);

        vendorInformationService.update(vendorInformation);

        out.print("{\"status\":\"success\"}");
        out.flush();
        return null;
    }

    // ================== HELPER METHOD ==================
    private String generateUniqueFileName(String newCleanedName, String existingStoredFileName, String folderPath) {

        if (newCleanedName == null || newCleanedName.isEmpty()) {
            return newCleanedName;
        }

        // ---- split & strip suffix from the NEW uploaded file name ----
        String newExt = "";
        String newBaseRaw = newCleanedName;
        int nd = newCleanedName.lastIndexOf(".");
        if (nd != -1) {
            newBaseRaw = newCleanedName.substring(0, nd);
            newExt = newCleanedName.substring(nd);
        }
        int[] newSuffixHolder = new int[1];
        String newRoot = stripTrailingTwoDigitSuffix(newBaseRaw, newSuffixHolder);
        int newSuffix = newSuffixHolder[0];

        if (existingStoredFileName == null || existingStoredFileName.isEmpty()) {
            return newCleanedName;
        }

        existingStoredFileName = existingStoredFileName.trim();
        int lastSlash = Math.max(existingStoredFileName.lastIndexOf("/"), existingStoredFileName.lastIndexOf("\\"));
        if (lastSlash != -1) {
            existingStoredFileName = existingStoredFileName.substring(lastSlash + 1);
        }

        // ---- split & strip suffix from the EXISTING stored file name ----
        String existingExt = "";
        String existingBaseRaw = existingStoredFileName;
        int ed = existingStoredFileName.lastIndexOf(".");
        if (ed != -1) {
            existingBaseRaw = existingStoredFileName.substring(0, ed);
            existingExt = existingStoredFileName.substring(ed);
        }
        int[] existingSuffixHolder = new int[1];
        String existingRoot = stripTrailingTwoDigitSuffix(existingBaseRaw, existingSuffixHolder);
        int existingSuffix = existingSuffixHolder[0];

        System.out.println("[generateUniqueFileName] newRoot=" + newRoot + " newSuffix=" + newSuffix
                + " | existingRoot=" + existingRoot + " existingSuffix=" + existingSuffix);

        if (!newRoot.equalsIgnoreCase(existingRoot) || !newExt.equalsIgnoreCase(existingExt)) {
            System.out.println("[generateUniqueFileName] Different file -> no increment: " + newCleanedName);
            return newCleanedName;
        }

        int nextCounter = Math.max(newSuffix, existingSuffix) + 1;

        String candidateName;
        File candidateFile;
        do {
            candidateName = newRoot + String.format("%02d", nextCounter) + newExt;
            candidateFile = new File(folderPath + candidateName);
            nextCounter++;
        } while (candidateFile.exists());

        System.out.println("[generateUniqueFileName] Incremented to: " + candidateName);

        return candidateName;
    }

    private String stripTrailingTwoDigitSuffix(String base, int[] suffixHolder) {
        suffixHolder[0] = 0;
        if (base != null && base.length() > 2) {
            String last2 = base.substring(base.length() - 2);
            if (last2.matches("\\d{2}")) {
                suffixHolder[0] = Integer.parseInt(last2);
                return base.substring(0, base.length() - 2);
            }
        }
        return base;
    }

